  (concat('email_template_', 'login_otp'), 'login_otp', 'Account', 'Login verification code', 'Your {{brandName}} login code', 'Use this code to complete sign in.', '<h1>Login verification code</h1><p>Hi {{userName}},</p><p>Use the one-time code for {{email}} to complete your login.</p><p>{{brandName}}</p>', 'Login verification code\n\nHi {{userName}},\n\nUse the one-time code for {{email}} to complete your login.\n\n{{brandName}}', true, 'migration'),
  (concat('email_template_', 'login_notice'), 'login_notice', 'Account', 'Login notice', 'Signed in to {{brandName}}', 'A login was detected on your account.', '<h1>Login notice</h1><p>Hi {{userName}},</p><p>Your account was signed in from {{loginIp}} at {{loginTime}}.</p><p>{{brandName}}</p>', 'Login notice\n\nHi {{userName}},\n\nYour account was signed in from {{loginIp}} at {{loginTime}}.\n\n{{brandName}}', true, 'migration'),
  (concat('email_template_', 'new_login_alert'), 'new_login_alert', 'Account', 'New login alert', 'New login to your {{brandName}} account', 'Security alert for a new login.', '<h1>New login alert</h1><p>Hi {{userName}},</p><p>We noticed a new login from {{loginIp}} at {{loginTime}}.</p><p>{{brandName}}</p>', 'New login alert\n\nHi {{userName}},\n\nWe noticed a new login from {{loginIp}} at {{loginTime}}.\n\n{{brandName}}', true, 'migration'),
